CREATE TABLE "personas" (
  "id" uuid PRIMARY KEY,
  "tipo_persona" varchar NOT NULL,
  "tutor_id" uuid,
  "nombre" varchar NOT NULL,
  "email" varchar UNIQUE,
  "password_hash" varchar,
  "auth_provider" varchar,
  "fecha_nacimiento" date,
  "sexo" varchar,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "mediciones" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" uuid NOT NULL,
  "fecha_medicion" date NOT NULL,
  "peso_kg" decimal,
  "talla_cm" decimal,
  "perimetro_cefalico_cm" decimal,
  "percentil_peso" decimal,
  "percentil_talla" decimal,
  "percentil_perimetro_cefalico" decimal,
  "fuera_de_rango" boolean NOT NULL DEFAULT false,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "estandar_percentiles" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sexo" varchar NOT NULL,
  "edad_meses" integer NOT NULL,
  "tipo_medida" varchar NOT NULL,
  "percentil" decimal NOT NULL,
  "valor" decimal NOT NULL
);

CREATE TABLE "alimentaciones" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" uuid NOT NULL,
  "fecha_hora" timestamp NOT NULL,
  "tipo" varchar NOT NULL,
  "cantidad_ml" decimal,
  "duracion_min" integer
);

CREATE TABLE "cambios_panal" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" uuid NOT NULL,
  "fecha_hora" timestamp NOT NULL,
  "tipo" varchar NOT NULL
);

CREATE TABLE "vacunas" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar NOT NULL,
  "edad_recomendada_dias" integer NOT NULL,
  "dosis_label" varchar,
  "descripcion" varchar
);

CREATE TABLE "vacunas_aplicadas" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" uuid NOT NULL,
  "vacuna_id" integer NOT NULL,
  "fecha_aplicacion" date NOT NULL,
  "lote" varchar
);

CREATE TABLE "consejos" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "titulo" varchar NOT NULL,
  "resumen" varchar NOT NULL,
  "contenido" text NOT NULL,
  "emoji" varchar,
  "categoria" varchar NOT NULL,
  "edad_min_meses" integer NOT NULL,
  "edad_max_meses" integer NOT NULL,
  "fuente" varchar
);

CREATE TABLE "notificaciones" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "persona_id" uuid NOT NULL,
  "tipo" varchar NOT NULL,
  "titulo" varchar NOT NULL,
  "cuerpo" varchar NOT NULL,
  "fecha_programada" timestamp NOT NULL,
  "fecha_envio" timestamp,
  "leida" boolean NOT NULL DEFAULT false
);

COMMENT ON COLUMN "personas"."tipo_persona" IS 'tutor | hijo (futuro: pediatra)';

COMMENT ON COLUMN "personas"."tutor_id" IS 'FK a esta misma tabla; solo si tipo_persona=hijo';

COMMENT ON COLUMN "personas"."nombre" IS 'Figma 02 "Nombre completo"; AuthSession.displayName';

COMMENT ON COLUMN "personas"."email" IS 'solo tutor - login (RF01)';

COMMENT ON COLUMN "personas"."password_hash" IS 'solo tutor; null si login social';

COMMENT ON COLUMN "personas"."auth_provider" IS 'email | google - solo tutor';

COMMENT ON COLUMN "personas"."fecha_nacimiento" IS 'obligatorio si tipo_persona=hijo (RN02)';

COMMENT ON COLUMN "personas"."sexo" IS 'M | F - obligatorio si tipo_persona=hijo (RN02)';

COMMENT ON COLUMN "mediciones"."persona_id" IS 'el hijo medido';

COMMENT ON COLUMN "estandar_percentiles"."sexo" IS 'M | F';

COMMENT ON COLUMN "estandar_percentiles"."tipo_medida" IS 'peso | talla | perimetro_cefalico';

COMMENT ON COLUMN "alimentaciones"."persona_id" IS 'el hijo alimentado';

COMMENT ON COLUMN "alimentaciones"."tipo" IS 'pecho | mamadera | solidos';

COMMENT ON COLUMN "cambios_panal"."persona_id" IS 'el hijo';

COMMENT ON COLUMN "cambios_panal"."tipo" IS 'orina | deposicion | mixto';

COMMENT ON COLUMN "vacunas"."edad_recomendada_dias" IS 'en dias, no meses: permite precision tipo "al nacer" = 0';

COMMENT ON COLUMN "vacunas"."dosis_label" IS 'ej: "3a dosis"; null en vacunas de dosis unica (BCG)';

COMMENT ON COLUMN "vacunas_aplicadas"."persona_id" IS 'el hijo vacunado';

COMMENT ON COLUMN "consejos"."resumen" IS 'texto corto para el listado (Figma 12), distinto del detalle completo';

COMMENT ON COLUMN "consejos"."contenido" IS 'detalle completo (Figma 13), varios parrafos';

COMMENT ON COLUMN "consejos"."emoji" IS 'icono de la tarjeta en el listado (Figma 12)';

COMMENT ON COLUMN "consejos"."categoria" IS 'alimentacion | desarrollo_motor | sueño | salud';

COMMENT ON COLUMN "notificaciones"."persona_id" IS 'el hijo';

COMMENT ON COLUMN "notificaciones"."tipo" IS 'control | vacuna | consejo';

COMMENT ON COLUMN "notificaciones"."titulo" IS 'ej: "Vacuna atrasada"';

COMMENT ON COLUMN "notificaciones"."cuerpo" IS 'ej: "La 3a dosis de Pentavalente de Lucia esta atrasada" - texto ya armado, no se regenera';

ALTER TABLE "personas" ADD FOREIGN KEY ("tutor_id") REFERENCES "personas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "mediciones" ADD FOREIGN KEY ("persona_id") REFERENCES "personas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "alimentaciones" ADD FOREIGN KEY ("persona_id") REFERENCES "personas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "cambios_panal" ADD FOREIGN KEY ("persona_id") REFERENCES "personas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "vacunas_aplicadas" ADD FOREIGN KEY ("persona_id") REFERENCES "personas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "vacunas_aplicadas" ADD FOREIGN KEY ("vacuna_id") REFERENCES "vacunas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "notificaciones" ADD FOREIGN KEY ("persona_id") REFERENCES "personas" ("id") DEFERRABLE INITIALLY IMMEDIATE;
